import java.util.Scanner;

public class Main {
    static final long INF = 1000000001L;
    static final int MAXN = 1123456;
    static final long MOD = 1000000007L;

    static long p, k;
    static boolean[] visited = new boolean[MAXN];

    static long timesCycle(long n) {
        long num = 1;
        for (long i = 0; i < n; i++) {
            num *= k;
            num %= p;
        }
        if (num == 1) return p;
        return 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextLong();
        k = sc.nextLong();

        if (k == 0 || k == 1) {
            long result = 1;
            for (long i = 0; i < p - 1; i++) {
                result *= p;
                result %= MOD;
            }
            if (k == 1) {
                System.out.println(result % MOD);
            } else {
                System.out.println(1);
            }
            sc.close();
            return;
        }

        long answer = 1;
        for (long i = 1; i < p; i++) {
            if (visited[(int)i]) continue;
            long x = i;
            long count = 0;
            while (!visited[(int)x]) {
                visited[(int)x] = true;
                x = (k * x) % p;
                count++;
            }
            answer *= timesCycle(count);
            answer %= MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}
